<script setup lang="ts">import {ref,onMounted,onUnmounted,watch} from 'vue';import {pmsApi} from './api';const props=defineProps<{active?:boolean;permissions:string[];departmentId?:number|null;projectId?:number|null}>();const emit=defineEmits(['department','project','create']);const open=ref(!!props.active),expanded=ref<number[]>([]),otherOpen=ref(false),data=ref<any>({departments:[],otherProjects:[]}),error=ref('');const canCreate=()=>props.permissions.includes('*')||props.permissions.includes('project-add');async function load(){try{data.value=await pmsApi('team-space');error.value='';restore();}catch(e){error.value=(e as Error).message;}}function currentDepartment(){return Number(new URLSearchParams(location.search).get('department'));}function restore(){if(!props.active)return;open.value=true;const q=new URLSearchParams(location.search);const departmentId=props.departmentId||Number(q.get('department'));const projectId=props.projectId||Number(q.get('project'));const d=data.value.departments.find((d:any)=>d.id===departmentId||d.projects.some((p:any)=>p.id===projectId));if(d&&!expanded.value.includes(d.id))expanded.value.push(d.id);if(data.value.otherProjects.some((p:any)=>p.id===projectId))otherOpen.value=true;}watch(()=>[props.active,props.departmentId,props.projectId],restore);function toggle(id:number){expanded.value=expanded.value.includes(id)?expanded.value.filter(i=>i!==id):[...expanded.value,id];}function update(){void load();}onMounted(()=>{void load();window.addEventListener('pms:changed',update);});onUnmounted(()=>window.removeEventListener('pms:changed',update));</script><template><div class="pms-team-navigation"><button class="pms-team-toggle" :class="{active}" :aria-expanded="open" @click="open=!open"><i aria-hidden="true" class="ti ti-users"></i><span>Team Space</span><i aria-hidden="true" class="ti" :class="open?'ti-chevron-down':'ti-chevron-right'"></i></button><div v-if="open" class="pms-team-tree"><p v-if="error" class="pms-team-empty" role="alert">{{error}}</p><div v-for="department in data.departments" :key="department.id"><div class="pms-team-department"><button class="pms-team-name" :class="{active:active&&department.id===(departmentId||currentDepartment())}" @click="department.can_open_board?emit('department',department.id):toggle(department.id)"><span class="pms-tree-dot"></span><span>{{department.dept_name}}</span></button><button class="pms-team-chevron" :aria-label="'Show projects in '+department.dept_name" :aria-expanded="expanded.includes(department.id)" @click="toggle(department.id)"><i aria-hidden="true" class="ti" :class="expanded.includes(department.id)?'ti-chevron-down':'ti-chevron-right'"></i></button><button v-if="canCreate()" class="pms-team-add" :aria-label="'Create project in '+department.dept_name" @click="emit('create',department.id)"><i aria-hidden="true" class="ti ti-plus"></i></button></div><div v-if="expanded.includes(department.id)" class="pms-team-projects"><button v-for="project in department.projects" :key="project.id" :class="{active:active&&project.id===projectId}" @click="emit('project',project.id)"><i aria-hidden="true" class="ti ti-layout-kanban"></i><span>{{project.name}}</span><small v-if="project.approval!=='approved'" class="badge bg-label-warning">{{project.approval}}</small></button><p v-if="!department.projects.length" class="pms-team-empty">No projects yet</p></div></div><template v-if="data.otherProjects.length"><button class="pms-team-other" :aria-expanded="otherOpen" @click="otherOpen=!otherOpen"><span class="pms-tree-dot"></span><span>Other projects</span><i aria-hidden="true" class="ti" :class="otherOpen?'ti-chevron-down':'ti-chevron-right'"></i></button><div v-if="otherOpen" class="pms-team-projects"><button v-for="project in data.otherProjects" :key="project.id" @click="emit('project',project.id)"><i aria-hidden="true" class="ti ti-layout-kanban"></i><span>{{project.name}}</span></button></div></template><p v-if="!error&&!data.departments.length&&!data.otherProjects.length" class="pms-team-empty">No accessible projects yet</p></div></div></template>